package com.example.chrono

/** Un texte en trois langues. */
class T3(private val fr: String, private val en: String, private val zh: String) {
    fun t(): String = when (Settings.lang) {
        Lang.FR -> fr
        Lang.EN -> en
        Lang.ZH -> zh
    }
}

/**
 * Explication d'un réglage, affichée par un appui long sur ce réglage (écran « Infos »,
 * ou au-dessus des curseurs min / max pour les curseurs). Les lignes sont séparées par « \n ».
 */
class Info(val key: String, val title: S, fr: String, en: String, zh: String) {
    private val text = T3(fr, en, zh)
    fun body(): String = text.t()

    companion object {
